// Create separate DAG states for different honest node views
let dag_state_group1 = Arc::new(RwLock::new(DagState::new(context.clone(), store1)));
let dag_state_group2 = Arc::new(RwLock::new(DagState::new(context.clone(), store2)));

// Byzantine node creates equivocating blocks
let block_x = create_block(round, byzantine_author, transactions_x);
let block_y = create_block(round, byzantine_author, transactions_y);
assert_eq!(block_x.slot(), block_y.slot());
assert_ne!(block_x.digest(), block_y.digest());

// Selective broadcast
dag_state_group1.accept_block(block_x);
dag_state_group2.accept_block(block_y);

// Build DAG chains and commit independently
let committed_group1 = commit_and_linearize(dag_state_group1);
let committed_group2 = commit_and_linearize(dag_state_group2);

// Safety check: sequences must be identical
assert_eq!(committed_group1, committed_group2, "Split commit detected!");
